/// Collect the handlers registered for currently-owned relics, in registry
/// (`RelicId`) order — the firing order every call-all dispatcher uses (the
/// `BTreeMap` is keyed by `RelicId`).
///
/// This replaces the per-call `listeners_*()` heap snapshot of EVERY globally-
/// registered listener. It takes one read lock, walks the `BTreeMap` once, and
/// keeps only the handlers whose relic the player currently owns, into a stack
/// `SmallVec` (no heap allocation for the common ≤8-owned-relics case).
/// Listeners for unowned relics — which all self-no-op on their
/// `player_owns_relic` guard before mutating anything — are never collected, so
/// the result is bit-identical to iterating ALL registered listeners and
/// letting the unowned ones return their no-op default. The ownership predicate
/// here (`state.relics.iter().any(|r| !r.is_melted && r.kind == k)`) is exactly
/// `helpers::player_owns_relic`. Bead `sts2-rs-b8z17`.
#[inline]
fn collect_owned_listeners<F: Copy + 'static>(
    registry: &ChannelRegistry<F>,
    state: &CombatState,
) -> smallvec::SmallVec<[F; 8]> {
    let mut owned: smallvec::SmallVec<[F; 8]> = smallvec::SmallVec::new();
    // No equipped relics ⇒ nothing can be owned; skip the whole registry
    // walk (which is O(registered listeners) with a `to_relic_kind` per
    // entry — ~2.6% of MCTS-search instructions on the 2026-07-03
    // realistic-deck callgrind when the player has no relics).
    if state.relics.is_empty() {
        return owned;
    }
    registry.for_each_listener(|id, f| {
        if id
            .to_relic_kind()
            .is_some_and(|k| state.relics.iter().any(|r| !r.is_melted && r.kind == k))
        {
            owned.push(f);
        }
    });
    owned
}

/// Dispatch `before_combat_start` to every registered listener.
pub fn dispatch_before_combat_start(state: &mut CombatState) -> EffectResult {
    if is_empty_before_combat_start() {
        return EffectResult::NotImplemented;
    }
    let listeners = listeners_before_combat_start();
    let mut any_resolved = false;
    for (_id, f) in listeners {
        if f(state) == EffectResult::Resolved {
            any_resolved = true;
        }
    }
    if any_resolved {
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

